mapper.select:
SELECT COUNT(*)
FROM USERS
WHERE LOWER(EMAIL) = #{email}

SELECT COUNT(*)
FROM USERS
WHERE PHONE = #{phone}
	AND USER_NUM != #{userNum}
	AND STATUS != 3

SELECT USER_NUM, EMAIL, PASSWD, USER_NAME, REAL_NAME, PHONE, BIRTH,
AUTH, LOGIN_TYPE, GOOGLE_ID, STATUS, REG_DATE, MODIFY_DATE
FROM USERS
WHERE REAL_NAME = #{realName}
AND PHONE = #{phone}
AND BIRTH = #{birth}
AND STATUS != 3
ORDER BY REG_DATE DESC
